    use edgerun_rasterizer::color_lut::{named_color, COLOR_LUT, NAMED_COLOR_COUNT};
    assert_eq!(NAMED_COLOR_COUNT, 148);
    // black
    // white
    // red
    // green
    // blue
    // yellow
    // cyan
    // magenta
    // orange
    // purple
    let (r, g, b, a) = named_color(0);
    assert_eq!((r, g, b, a), (0x00, 0x00, 0x00, 0xFF), "black");
    let (r, g, b, a) = named_color(1);
    assert_eq!((r, g, b, a), (0xFF, 0xFF, 0xFF, 0xFF), "white");
    let (r, g, b, a) = named_color(2);
    assert_eq!((r, g, b, a), (0xFF, 0x00, 0x00, 0xFF), "red");
    let (r, g, b, a) = named_color(3);
    assert_eq!((r, g, b, a), (0x00, 0x80, 0x00, 0xFF), "green");
    let (r, g, b, a) = named_color(4);
