#[test]
fn gradient_stop_count_min() {
    use edgerun_rasterizer::framebuffer::Framebuffer;
    use edgerun_rasterizer::scanline::{RasterCommand, rasterize};
    use edgerun_rasterizer::gradient::GradientStop;
    let mut pixels = vec![0u8; 8 * 8 * 4];
    {
        let mut fb = Framebuffer::new(&mut pixels, 8, 8);
        fb.clear();
    }
    // Capture bg state
    let bg_b = pixels[0];
    let bg_g = pixels[1];
    let bg_r = pixels[2];
    {
        let mut fb = Framebuffer::new(&mut pixels, 8, 8);
        // Gradient with < 2 stops should be a no-op
        let cmds = [RasterCommand::LinearGradient {
            x: 0, y: 0, w: 8, h: 8, angle: 0.0,
            stops: vec![GradientStop { r: 0xFF, g: 0, b: 0, a: 255, position: 0.0 }],
        }];
        rasterize(&mut fb, &cmds);
    }
    // Should remain background
    assert_eq!(pixels[0], bg_b, "B channel unchanged");
    assert_eq!(pixels[1], bg_g, "G channel unchanged");
    assert_eq!(pixels[2], bg_r, "R channel unchanged");
}

#[test]
fn linear_gradient_endpoints() {
    use edgerun_rasterizer::framebuffer::Framebuffer;
    use edgerun_rasterizer::scanline::{RasterCommand, rasterize};
    use edgerun_rasterizer::gradient::GradientStop;
    let mut pixels = vec![0u8; 8 * 2 * 4];
    let mut fb = Framebuffer::new(&mut pixels, 8, 2);
    fb.clear();
    let cmds = [RasterCommand::LinearGradient {
        x: 0, y: 0, w: 8, h: 2, angle: 0.0,
        stops: vec![
            GradientStop { r: 0xFF, g: 0, b: 0, a: 255, position: 0.0 },
            GradientStop { r: 0, g: 0, b: 0xFF, a: 255, position: 1.0 },
        ],
    }];
    rasterize(&mut fb, &cmds);
    // Left pixel should be closer to red
    let left_r = pixels[2]; // pixel 0, R channel
    // Right pixel should be closer to blue
    let right_b = pixels[7 * 4]; // pixel 7, B channel
    assert!(left_r > 0, "left pixel should have some red");
    assert!(right_b > 0, "right pixel should have some blue");
}

