#[test]
fn text_renders_non_whitespace() {
    use edgerun_rasterizer::framebuffer::Framebuffer;
    use edgerun_rasterizer::scanline::{RasterCommand, rasterize};
    let mut pixels = vec![0u8; 32 * 8 * 4];
    let mut fb = Framebuffer::new(&mut pixels, 32, 8);
    fb.clear();
    let cmds = [RasterCommand::Text {
        x: 0, y: 0,
        text: "Hi".to_string(),
        r: 0xFF, g: 0xFF, b: 0xFF,
    }];
    rasterize(&mut fb, &cmds);
    // At least some pixels should have changed from background
    let changed = pixels.iter().enumerate().filter(|(i, &v)| {
        match i % 4 { 0 => v != 0x1a, 1 => v != 0x1a, 2 => v != 0x2e, _ => false }
    }).count();
    assert!(changed > 0, "text should modify at least some pixels (modified {})", changed);
}

